        /// <summary>Hauteur (0..1) de la ligne médiane à la position "along" (0 = tête, 1 = queue).</summary>
        public static float CenterAt(int type, int frame, float along)
        {
            var cl = Centerline[type][frame % Centerline[type].Length];
            float f = UnityEngine.Mathf.Clamp01(along) * (cl.Length - 1);
            int i = UnityEngine.Mathf.Min((int)f, cl.Length - 2);
            return UnityEngine.Mathf.Lerp(cl[i], cl[i + 1], f - i);
        }
